import{_ as i}from"./chunks/files.B17OUyrr.js";import{_ as s,c as r,o as t,a2 as a}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Découvrez qDiff","description":"Une courte présentation de la comparaison de fichiers, de dossiers et de projets avec qDiff sur votre Mac.","frontmatter":{"title":"Découvrez qDiff","description":"Une courte présentation de la comparaison de fichiers, de dossiers et de projets avec qDiff sur votre Mac."},"headers":[],"relativePath":"fr/guide/introduction.md","filePath":"fr/guide/introduction.md","lastUpdated":1794296122000}'),o={name:"fr/guide/introduction.md"};function n(u,e,l,c,d,f){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="decouvrez-qdiff" tabindex="-1">Découvrez qDiff <a class="header-anchor" href="#decouvrez-qdiff" aria-label="Permalink to &quot;Découvrez qDiff&quot;">​</a></h1><p>qDiff répond à une seule question : <strong>qu&#39;est-ce qui a changé ?</strong> Placez deux versions côte à côte et la moindre différence est signalée par une couleur : vous n&#39;avez plus à comparer les lignes une à une à l&#39;œil nu.</p><img src="'+i+'" alt="Deux fichiers comparés côte à côte" class="guide-shot"><h2 id="trois-usages-frequents" tabindex="-1">Trois usages fréquents <a class="header-anchor" href="#trois-usages-frequents" aria-label="Permalink to &quot;Trois usages fréquents&quot;">​</a></h2><ul><li><strong>Deux fichiers</strong> — un brouillon et sa révision, un fichier de configuration avant et après, deux exports du même outil. Les mots modifiés sont surlignés à l&#39;intérieur de la ligne.</li><li><strong>Deux dossiers</strong> — un dossier de travail et sa sauvegarde. Les fichiers nouveaux, modifiés et manquants se repèrent d&#39;un coup d&#39;œil, et vous pouvez resynchroniser les deux côtés.</li><li><strong>Un dossier de projet</strong> — tout ce que vous avez touché, réuni dans une seule liste. Lisez chaque modification et validez sans changer de fenêtre.</li></ul><p>Les images, les archives compressées et les fichiers qui ne sont pas du texte brut sont également les bienvenus. <a href="./more.html">Découvrez d&#39;autres façons de comparer</a>.</p><h2 id="demarrez-en-trois-etapes" tabindex="-1">Démarrez en trois étapes <a class="header-anchor" href="#demarrez-en-trois-etapes" aria-label="Permalink to &quot;Démarrez en trois étapes&quot;">​</a></h2><ol><li>Ouvrez qDiff et déposez deux fichiers ou dossiers dans la fenêtre — ou choisissez-les depuis le menu <strong>Fichier</strong>.</li><li>Regardez les lignes colorées. Cliquez sur la petite carte sur le côté, ou utilisez les boutons précédent / suivant pour parcourir chaque modification.</li><li>Modifiez, copiez ou synchronisez ce qui doit être corrigé. Enregistrez une image de la comparaison si quelqu&#39;un d&#39;autre doit la voir.</li></ol><div class="tip custom-block"><p class="custom-block-title">Aucune configuration nécessaire</p><p>Il n&#39;y a aucun compte à créer et rien à régler avant la première comparaison. Tout fonctionne hors ligne.</p></div><h2 id="gratuit-et-confidentiel" tabindex="-1">Gratuit et confidentiel <a class="header-anchor" href="#gratuit-et-confidentiel" aria-label="Permalink to &quot;Gratuit et confidentiel&quot;">​</a></h2><p>Toutes les comparaisons sont disponibles gratuitement. La version gratuite affiche seulement une petite marque dans la barre d&#39;onglets ; un achat unique la retire. qDiff ne lit que les fichiers que vous choisissez et n&#39;envoie rien nulle part — consultez la <a href="./../privacy/">Politique de confidentialité</a> pour les détails.</p><h2 id="besoin-d-aide" tabindex="-1">Besoin d&#39;aide ? <a class="header-anchor" href="#besoin-d-aide" aria-label="Permalink to &quot;Besoin d&#39;aide ?&quot;">​</a></h2><p>La <a href="./faq.html">FAQ</a> répond aux questions les plus courantes. Si quelque chose semble encore anormal, <a href="./../guide/support.html">écrivez-nous</a> et nous vous aiderons.</p>',13)])])}const q=s(o,[["render",n]]);export{m as __pageData,q as default};
